function checkKey(apiKey) {
  if (!apiKey || apiKey.length === 0) return { error: "missing X-API-Key header" }
  var hash = $security.sha256(apiKey)
  var client = null
  try { client = $app.findFirstRecordByData("mock_clients", "api_key_hash", hash) } catch (err) {}
  if (!client) return { error: "invalid API key" }
  if (!client.getBool("active")) return { error: "client is disabled" }
  return { client: client }
}

function ensureConfig(clientId) {
  var cfg = null
  try { cfg = $app.findFirstRecordByData("mock_config", "client", clientId) } catch (err) {}
  if (!cfg) {
    var col = $app.findCollectionByNameOrId("mock_config")
    cfg = new Record(col)
    cfg.set("client", clientId)
    cfg.set("name", "default"); cfg.set("llm_author_model", "google/gemini-2.5-flash"); cfg.set("llm_proofread_model", "qwen/qwen3.5-flash-02-23"); cfg.set("llm_repair_model", "google/gemini-2.5-flash"); cfg.set("image_primary", "z-image"); cfg.set("image_fallback", "p-image-ideogram-1k"); cfg.set("tts_model", "fish-audio/s2.1-pro-free:free"); cfg.set("tts_fallback_model", "microsoft/mai-voice-2-flash"); cfg.set("tts_fallback_voice", "ko-KR-Haena"); cfg.set("question_count", 40); cfg.set("reading_count", 20); cfg.set("image_count", 22); cfg.set("image_count_min", 18); cfg.set("image_count_max", 26); cfg.set("difficulty_profile", "creative+difficult"); cfg.set("marks_per_question", 1); cfg.set("max_tokens", 32000); cfg.set("temperature", 0.7); cfg.set("timeout_s", 600); cfg.set("retries", 3); cfg.set("img_retries", 4); cfg.set("push_pb_base", "https://ubt.wts.com.np"); cfg.set("push_pb_email", "shiva@cld.com.np"); cfg.set("push_pb_pass", ""); cfg.set("push_subject_id", "illfosglou0e3j6"); cfg.set("push_exam_type", "mock"); cfg.set("push_exam_status", "draft"); cfg.set("audio_gap_ms", 300); cfg.set("sample_rate", 44100); cfg.set("audio_workers", 4); cfg.set("prompts_json", {}); cfg.set("active", true); 
    $app.save(cfg)
  }
  return cfg
}

try {
  ensureCollections()
  var isSuper = false
  if (e.auth) { try { $app.findRecordById("_superusers", e.auth.id); isSuper = true } catch (err2) {} }
  var client = null
  if (!isSuper) {
    var keyRes = checkKey(e.request.header.get("X-API-Key"))
    if (keyRes.error) return e.json(401, { error: keyRes.error })
    client = keyRes.client
  }
  var id = e.request.pathValue("id")
  var rec = null
  try { rec = $app.findRecordById("mock_jobs", id) } catch (err) {}
  if (!rec) return e.json(404, { error: "job not found" })
  if (!isSuper && rec.getString("client") !== client.id) return e.json(403, { error: "forbidden" })
  var cname = ""
  try { cname = $app.findRecordById("mock_clients", rec.getString("client")).getString("name") } catch (err3) {}
  return e.json(200, {
    id: rec.id,
    client: rec.getString("client"),
    client_name: cname,
    status: rec.getString("status"),
    kind: rec.getString("kind") || "full",
    count: rec.getInt("count"),
    difficulty: rec.getString("difficulty"),
    overrides: rec.get("overrides"),
    log: rec.getString("log"),
    report: rec.get("report"),
    error: rec.getString("error"),
    pushed: rec.getBool("pushed"),
    created: rec.getString("created"),
    updated: rec.getString("updated")
  })
} catch (err) {
  return e.json(500, { error: String(err) })
}

